// Writes supabase/seed.sql from src/lib/data/seed.ts so both data modes start identical.
// Run: npm run db:seed-sql
import { writeFileSync } from "node:fs";
import { seedCategories, seedProducts } from "../src/lib/data/seed";

const q = (v: unknown) => (v === null || v === undefined ? "null" : typeof v === "boolean" || typeof v === "number" ? String(v) : `'${String(v).replace(/'/g, "''")}'`);

const lines: string[] = [
  "-- Generated by scripts/generate-seed-sql.ts. Starter catalogue: every product is needs_review = true.",
  "-- Staff must confirm or delete these entries before launch.",
  "begin;",
];
const catCols = ["id", "slug", "parent_id", "name_en", "name_hi", "name_pa", "image_url", "sort_order", "featured"] as const;
// parents first so the foreign key is satisfied
const cats = [...seedCategories].sort((a, b) => Number(!!a.parent_id) - Number(!!b.parent_id));
for (const c of cats) {
  lines.push(`insert into public.categories (${catCols.join(", ")}) values (${catCols.map((k) => q(c[k])).join(", ")}) on conflict (id) do nothing;`);
}
const prodCols = [
  "id", "slug", "name", "brand", "manufacturer", "generic_name", "pack_size", "category_id", "description", "information",
  "image_url", "pack_style", "availability", "rx_class", "published", "featured", "needs_review",
] as const;
for (const p of seedProducts) {
  lines.push(`insert into public.products (${prodCols.join(", ")}) values (${prodCols.map((k) => q(p[k])).join(", ")}) on conflict (id) do nothing;`);
}
lines.push("commit;", "");
writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`supabase/seed.sql: ${cats.length} categories, ${seedProducts.length} products`);
